package com.jiugeng.erp.watch;
import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class WatchControllerTest{
 static final String PASSWORD="Watch-Test-42";@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;
 @BeforeEach void reset(){jdbc.update("DELETE FROM product_development");jdbc.update("DELETE FROM watch_new_product_event");jdbc.update("UPDATE watch_store SET baseline_run_id=NULL");jdbc.update("DELETE FROM watch_baseline_asin");jdbc.update("DELETE FROM watch_snapshot_asin");jdbc.update("DELETE FROM watch_run");jdbc.update("DELETE FROM watch_store");jdbc.update("DELETE FROM selection_candidate_evidence");jdbc.update("DELETE FROM selection_candidate_note");jdbc.update("DELETE FROM selection_candidate_tag");jdbc.update("DELETE FROM selection_candidate");jdbc.update("DELETE FROM iam_password_reset_challenge");jdbc.update("DELETE FROM audit_event");jdbc.update("DELETE FROM iam_session");jdbc.update("DELETE FROM iam_user");}
 @Test void safeBaselineDiffAndCandidateTraceSurviveFormalWorkflow()throws Exception{String token=user("watcher","SELECTION");String store=createStore(token,"STORE-A");run(token,store,"run-1","SUCCEEDED",2,1,true,List.of("B0BASE0001","B0BASE0002")).andExpect(jsonPath("$.baselineChanged").value(true)).andExpect(jsonPath("$.events.length()").value(0));String baseline=jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store);
  run(token,store,"run-empty","SUCCEEDED",0,1,true,List.of()).andExpect(jsonPath("$.baselineChanged").value(false)).andExpect(jsonPath("$.run.integrityStatus").value("INCOMPLETE"));assertThat(jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store)).isEqualTo(baseline);
  run(token,store,"run-bad","SUCCEEDED",1,2,false,List.of("B0BASE0001")).andExpect(jsonPath("$.baselineChanged").value(false));assertThat(jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store)).isEqualTo(baseline);
  String response=run(token,store,"run-2","SUCCEEDED",3,1,true,List.of("B0BASE0001","B0BASE0002","B0NEW00001")).andExpect(jsonPath("$.events.length()").value(1)).andReturn().getResponse().getContentAsString();String eventId=json.readTree(response).at("/events/0/id").asText();
  run(token,store,"run-3","SUCCEEDED",3,1,true,List.of("B0BASE0001","B0BASE0002","B0NEW00001")).andExpect(jsonPath("$.events.length()").value(0));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM watch_new_product_event",Integer.class)).isEqualTo(1);
  String confirmed=mvc.perform(post("/api/v1/watch/events/{id}/confirm",eventId).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.item.status").value("CONFIRMED")).andReturn().getResponse().getContentAsString();String candidate=json.readTree(confirmed).at("/candidate/id").asText();mvc.perform(post("/api/v1/watch/events/{id}/confirm",eventId).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.replayed").value(true)).andExpect(jsonPath("$.candidate.id").value(candidate));
  assertThat(jdbc.queryForMap("SELECT source,source_store,source_run_id,source_event_id FROM selection_candidate WHERE id=?",candidate)).containsEntry("SOURCE","WATCH").containsEntry("SOURCE_STORE","监控店铺").containsEntry("SOURCE_EVENT_ID",eventId);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_event WHERE resource_type='WATCH'",Integer.class)).isGreaterThanOrEqualTo(6);
 }
 @Test void requestIdAndPermissionsAreEnforced()throws Exception{String writer=user("watcher","SELECTION");String store=createStore(writer,"STORE-B");run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0IDEMP0001")).andExpect(jsonPath("$.replayed").value(false));run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0IDEMP0001")).andExpect(jsonPath("$.replayed").value(true));run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0DIFFER001")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("WATCH_REQUEST_CONFLICT"));String read=user("product","PRODUCT_MATERIAL");mvc.perform(get("/api/v1/watch/stores").header("Authorization",bearer(read))).andExpect(status().isOk());mvc.perform(post("/api/v1/watch/stores").header("Authorization",bearer(read)).contentType(MediaType.APPLICATION_JSON).content("{\"storeKey\":\"DENIED\",\"storeName\":\"Denied\",\"sourceUrl\":\"https://example.com\"}")).andExpect(status().isForbidden());}
 @Test void remarksAndRemovalAreVersionedAuthorizedAndRecoverable() throws Exception {
  String writer=user("editor","SELECTION"),reader=user("reader","PRODUCT_MATERIAL"),id=createStore(writer,"TESTSELLER");
  run(writer,id,"baseline","SUCCEEDED",1,1,true,List.of("B0TEST0001"));
  long v=jdbc.queryForObject("SELECT version FROM watch_store WHERE id=?",Long.class,id);
  String body=json.writeValueAsString(Map.of("version",v,"remark","Updated note"));
  mvc.perform(patch("/api/v1/watch/stores/{id}/remark",id).header("Authorization",bearer(reader)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());
  mvc.perform(patch("/api/v1/watch/stores/{id}/remark",id).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.remark").value("Updated note"));
  mvc.perform(patch("/api/v1/watch/stores/{id}/remark",id).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isConflict());
  mvc.perform(delete("/api/v1/watch/stores/{id}",id).param("version",""+(v+1)).header("Authorization",bearer(reader))).andExpect(status().isForbidden());
  mvc.perform(delete("/api/v1/watch/stores/{id}",id).param("version",""+v).header("Authorization",bearer(writer))).andExpect(status().isConflict());
  mvc.perform(delete("/api/v1/watch/stores/{id}",id).param("version",""+(v+1)).header("Authorization",bearer(writer))).andExpect(status().isOk());
  mvc.perform(get("/api/v1/watch/stores").header("Authorization",bearer(writer))).andExpect(jsonPath("$.length()").value(0));
  assertThat(jdbc.queryForObject("SELECT status FROM watch_store WHERE id=?",String.class,id)).isEqualTo("DISABLED");
  assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM watch_run WHERE store_id=?",Integer.class,id)).isEqualTo(1);
  mvc.perform(post("/api/v1/watch/stores/from-url").header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content("{\"url\":\"https://www.amazon.com/sp?seller=TESTSELLER\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id)).andExpect(jsonPath("$.remark").value("Updated note"));
 }

 @Test void timingRequiresWatchPermissionAndEventsAreStoreScoped()throws Exception{
  String token=user("timing-watcher","SELECTION"),denied=user("timing-denied","PRODUCT_MATERIAL");String id=createStore(token,"TIMING-SYNTHETIC"),other=createStore(token,"OTHER-SYNTHETIC");
  jdbc.update("INSERT INTO collection_schedule(id,kind,target_id,provider,enabled,next_at) VALUES(?,'STORE',?,'synthetic',TRUE,CURRENT_TIMESTAMP)",UUID.randomUUID().toString(),id);
  String path="/api/v1/collection/stores/"+id+"/timing";
  mvc.perform(get(path)).andExpect(status().isUnauthorized());
  mvc.perform(put(path).header("Authorization",bearer(denied)).contentType(MediaType.APPLICATION_JSON).content("{\"intervalDays\":2,\"localTime\":\"08:00\",\"timeZone\":\"Asia/Shanghai\",\"version\":0}")).andExpect(status().isForbidden());
  mvc.perform(put(path).header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content("{\"intervalDays\":2,\"localTime\":\"08:00\",\"timeZone\":\"Asia/Shanghai\",\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.intervalDays").value(2)).andExpect(jsonPath("$.version").value(1));
  run(token,id,"timing-baseline","SUCCEEDED",1,1,true,List.of("B0BASE0001"));run(token,id,"timing-new","SUCCEEDED",2,1,true,List.of("B0BASE0001","B0NEW00001"));
  mvc.perform(get("/api/v1/watch/stores/{id}/events",id).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(1));
  mvc.perform(get("/api/v1/watch/stores/{id}/events",other).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(0));
 }
 @Autowired WatchNoveltyTarget novelty;
 @Test void noveltyIsIndependentVersionedAndKeepsDiscoveryDate()throws Exception{
  String writer=user("novelty-writer","SELECTION"),reader=user("novelty-reader","PRODUCT_MATERIAL"),store=createStore(writer,"NOVELTY-SYNTHETIC");
  run(writer,store,"novelty-base","SUCCEEDED",1,1,true,List.of("B0BASE0001"));
  run(writer,store,"novelty-new","SUCCEEDED",2,1,true,List.of("B0BASE0001","B0NEW00001"));
  String id=jdbc.queryForObject("SELECT id FROM watch_new_product_event WHERE store_id=?",String.class,store);
  jdbc.update("UPDATE watch_new_product_event SET first_detected_at=? WHERE id=?",java.sql.Timestamp.from(java.time.Instant.parse("2026-10-27T08:00:00Z")),id);
  jdbc.update("UPDATE watch_run SET adapter_name='amazon-public-us' WHERE id=(SELECT detected_run_id FROM watch_new_product_event WHERE id=?)",id);
  String path="/api/v1/watch/events/"+id+"/novelty";
  mvc.perform(put(path).header("Authorization",bearer(reader)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"action\":\"CONFIRMED\"}")).andExpect(status().isForbidden());
  mvc.perform(post(path+"/collect").header("Authorization",bearer(reader))).andExpect(status().isForbidden());
  mvc.perform(put(path).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"action\":\"BAD\"}")).andExpect(status().isBadRequest());
  mvc.perform(put(path).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"action\":\"EXCLUDED\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.noveltyOverride").value("EXCLUDED"));
  novelty.apply(new com.jiugeng.erp.collection.CollectionAdapter.Target("WATCH_NOVELTY",id,"B0NEW00001",0),"amazon-public-us","test-job",new com.jiugeng.erp.collection.CollectionAdapter.Observation(java.time.Instant.parse("2026-11-15T12:00:00Z"),"PARTIAL",true,json.createObjectNode().put("listedAt","August 28, 2026")));
  mvc.perform(get("/api/v1/watch/stores/{id}/events",store).header("Authorization",bearer(writer))).andExpect(jsonPath("$[0].noveltyStatus").value("CANDIDATE")).andExpect(jsonPath("$[0].availableDate").value("2026-08-28")).andExpect(jsonPath("$[0].noveltyOverride").value("EXCLUDED")).andExpect(jsonPath("$[0].detectedAt").value("2026-10-27T08:00:00Z"));
  mvc.perform(put(path).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"action\":\"RESET\"}")).andExpect(status().isConflict());
  mvc.perform(put(path).header("Authorization",bearer(writer)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":1,\"action\":\"RESET\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.noveltyOverride").isEmpty());
  assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM watch_new_product_event WHERE store_id=?",Integer.class,store)).isEqualTo(1);
  assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_event WHERE action='WATCH_NOVELTY_MARK'",Integer.class)).isEqualTo(2);
 }
 private String createStore(String token,String key)throws Exception{String body=mvc.perform(post("/api/v1/watch/stores").header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("storeKey",key,"storeName","监控店铺","sourceUrl","https://example.com/store")))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("id").asText();}
 private org.springframework.test.web.servlet.ResultActions run(String token,String store,String request,String status,int count,int pages,boolean complete,List<String> asins)throws Exception{return mvc.perform(post("/api/v1/watch/stores/{id}/runs",store).header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("requestId",request,"status",status,"itemCount",count,"pageCount",pages,"pagesComplete",complete,"asins",asins))));}
 private String user(String name,String role)throws Exception{String id=UUID.randomUUID().toString();var encoder=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();jdbc.update("INSERT INTO iam_user (id,login_name,display_name,password_hash,role,status,must_change_password) VALUES (?,?,?,?,?,'ENABLED',FALSE)",id,name,name,encoder.encode(PASSWORD),role);String body=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("loginName",name,"password",PASSWORD)))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("token").asText();}private String bearer(String token){return "Bearer "+token;}
}
